INSERT INTO `everlake_build_stage` (`n`, `ID`, `RewardText`) VALUES
(1, 79365, 'Our wind riders have found something, but they have been unable to get close enough to assess the situation. Were you able to find anything that might help us?'),
(2, 79366, 'The rumbling ground fell silent and in my heart I knew you had saved us. You have our gratitude, $N. You do your Earthen Ring proud.'),
(3, 79442, 'Ah, this be a powerful artifact, friend! I haven''t crafted with some''ting like this in a long time.$B$BYou take good care o'' dis now, ya here? Looks like ya went through plenty to get it!'),
(4, 95663, 'Arrival of the courageous few? Mind your voice.'),
(5, 95682, 'Don''t mind me snatching that right out of your hands.$B$BI recognized that orcish scrawl. So they''re hoping to appease Rend? A fruitless and wasted effort.$B$BNo matter, this is highly valuable knowledge for the dark lady to consider.$B$BHere, I won''t be taking any of this with me--and don''t talk about the mission, grunt.'),
(6, 98069, 'Thank you, $N. These supplies will help get us through until the next shipment arrives.')
INSERT INTO `quest_offer_reward` (`ID`, `RewardText`, `VerifiedBuild`) SELECT p.`ID`, p.`RewardText`, 0 FROM `everlake_build_stage` p WHERE p.`free` = 1 ORDER BY p.`n`;
INSERT INTO `everlake_import_rows` (`tbl`, `k1`, `file`, `note`) SELECT 'quest_offer_reward', p.`ID`, '2026_11_14_950_world_everlake_build.sql', s.`note` FROM `everlake_build_stage` p JOIN `everlake_build_quests` s ON s.`ID` = p.`ID` WHERE p.`free` = 1;
INSERT INTO `everlake_build_stage` (`n`, `ID`, `CompletionText`) VALUES
(1, 79366, 'Have you any news of the storm?'),
(2, 79442, 'Great battle with de elements, mm? Tings turned out how they was always meant to.$B$BBut since you here, what brings you to ol'' Bath''rah?'),
(3, 95682, 'We''re here to get the important job done. If you can help, prove it.'),
(4, 98069, 'Have you been able to recover the supplies the harpies stole?')
INSERT INTO `quest_request_items` (`ID`, `CompletionText`, `VerifiedBuild`) SELECT p.`ID`, p.`CompletionText`, 0 FROM `everlake_build_stage` p WHERE p.`free` = 1 ORDER BY p.`n`;
INSERT INTO `everlake_import_rows` (`tbl`, `k1`, `file`, `note`) SELECT 'quest_request_items', p.`ID`, '2026_11_14_950_world_everlake_build.sql', s.`note` FROM `everlake_build_stage` p JOIN `everlake_build_quests` s ON s.`ID` = p.`ID` WHERE p.`free` = 1;
